param(
 [ValidateSet('create','kiosk','normal','menu')][string]$Action='menu',
 [string]$BackgroundImage,
 [string]$TimeFontSize,
 [string]$DateFontSize,
 [string]$FontFamily,
 [string]$FontColor,
 [string]$TimeFormat,
 [string]$DateFormat,
 [switch]$DebugMode
)

$ScriptFolder = Split-Path -Parent $PSCommandPath
$HtmlPath = Join-Path $ScriptFolder 'kiosk.html'
$ConfigPath = Join-Path $ScriptFolder 'kiosk-config.json'
$WindowsWallpapersPath = Join-Path $env:WINDIR 'Web'

$FontSizePresets = [ordered]@{'Small (5vw)'='5vw';'Medium (9vw)'='9vw';'Large (12vw)'='12vw';'Extra Large (15vw)'='15vw'}
$FontFamilyPresets = [ordered]@{'Default (Segoe UI, Arial)'='Segoe UI, Arial, sans-serif';'Modern (Helvetica, Arial)'='Helvetica, Arial, sans-serif';'Monospace (Courier New)'="'Courier New', monospace";'Serif (Georgia)'='Georgia, serif'}
$FontColorPresets = [ordered]@{'White'='#FFFFFF';'Light Gray'='#E0E0E0';'Yellow'='#FFFF00';'Cyan'='#00FFFF';'Green'='#00FF00'}
$BackgroundColorPresets = [ordered]@{'Red'='#FF0000';'Green'='#00FF00';'Blue'='#0000FF';'Cyan'='#00FFFF';'Magenta'='#FF00FF';'Yellow'='#FFFF00';'Black'='#000000';'Gray'='#808080'}
$TimeFormatPresets = [ordered]@{'12-hour (2:45 PM)'='hh:mm A';'12-hour with seconds'='hh:mm:ss A';'24-hour (14:45)'='HH:mm';'24-hour with seconds'='HH:mm:ss'}
$DateFormatPresets = [ordered]@{'Full (Monday, January 5, 2026)'='dddd, MMMM D, YYYY';'Short (Mon, Jan 5, 2026)'='ddd, MMM D, YYYY';'Date only (01/05/2026)'='MM/DD/YYYY';'Month and day (January 5)'='MMMM D'}

function New-DefaultConfig { [pscustomobject]@{BackgroundFileName='';BackgroundColor='';TimeFontSize='9vw';DateFontSize='3vw';FontFamily='Segoe UI, Arial, sans-serif';FontColor='#FFFFFF';OverlayOpacity=0.18;TimeFormat='hh:mm A';DateFormat='dddd, MMMM D, YYYY';TextShadow='0 2px 6px rgba(0,0,0,0.6)'} }
function Load-Config { if(Test-Path -LiteralPath $ConfigPath){ try { Get-Content -LiteralPath $ConfigPath -Raw | ConvertFrom-Json } catch { Write-Warning 'Invalid config; using defaults.'; New-DefaultConfig } } else { New-DefaultConfig } }
function Save-Config($Config){ if(-not $DebugMode){ $Config | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $ConfigPath -Encoding UTF8 } }
function Set-Cfg($Config,$Name,$Value){ if($null -eq $Config.PSObject.Properties[$Name]){$Config|Add-Member NoteProperty $Name $Value}else{$Config.$Name=$Value} }
function Normalize-HexColor([string]$Value){ if([string]::IsNullOrWhiteSpace($Value)){return $null}; $v=$Value.Trim().TrimStart('#').ToUpperInvariant(); if($v -match '^[0-9A-F]{3}$'){$v=''+$v[0]+$v[0]+$v[1]+$v[1]+$v[2]+$v[2]}; if($v -notmatch '^[0-9A-F]{6}$'){return $null}; return "#$v" }
function Test-Image([string]$Path){ if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return $false}; $b=[IO.File]::ReadAllBytes($Path); if($b.Length -ge 8 -and $b[0]-eq 0x89 -and $b[1]-eq 0x50 -and $b[2]-eq 0x4E -and $b[3]-eq 0x47){return 'png'}; if($b.Length -ge 2 -and $b[0]-eq 0xFF -and $b[1]-eq 0xD8){return 'jpg'}; return $false }
function Copy-Background([string]$Path){ $type=Test-Image $Path; if(-not $type){Write-Warning 'Background must be a valid PNG or JPEG.';return $null}; $name="background.$type"; $dest=Join-Path $ScriptFolder $name; if([IO.Path]::GetFullPath($Path) -ne [IO.Path]::GetFullPath($dest)){Copy-Item -LiteralPath $Path -Destination $dest -Force}; foreach($old in 'background.jpg','background.png'){if($old -ne $name){Remove-Item -LiteralPath (Join-Path $ScriptFolder $old) -Force -ErrorAction SilentlyContinue}}; return $name }
function Get-Wallpapers { $h=[ordered]@{}; if(Test-Path -LiteralPath $WindowsWallpapersPath){ Get-ChildItem -LiteralPath $WindowsWallpapersPath -File -Recurse -ErrorAction SilentlyContinue | Where-Object {$_.Extension -match '^\.(jpg|jpeg|png)$'} | Sort-Object FullName | ForEach-Object { $label=$_.FullName.Substring($WindowsWallpapersPath.TrimEnd('\').Length).TrimStart('\'); $h[$label]=$_.FullName } }; return $h }
function Select-Map($Map,[string]$Title){ Clear-Host; Write-Host "=== $Title ===`n"; $keys=@($Map.Keys); for($i=0;$i-lt$keys.Count;$i++){Write-Host "$($i+1)) $($keys[$i])"}; Write-Host 'B) Back'; $c=Read-Host 'Choose'; if($c -match '^[Bb]$'){return $null}; $n=0;if(-not[int]::TryParse($c,[ref]$n) -or $n-lt 1 -or $n-gt $keys.Count){Write-Warning 'Invalid choice';Read-Host 'Press Enter';return $null}; return $Map[$keys[$n-1]] }
function Edit-Background($Config){ while($true){Clear-Host;Write-Host "=== Background ===`n1) Windows wallpaper`n2) Solid color`n3) Default dark blue`nB) Back";$c=Read-Host 'Choose';switch($c){'1'{$w=Get-Wallpapers;if($w.Count-eq 0){Write-Warning "No wallpapers found under $WindowsWallpapersPath";Read-Host 'Press Enter';continue};$p=Select-Map $w 'Windows Wallpapers';if($p){$f=Copy-Background $p;if($f){Set-Cfg $Config BackgroundFileName $f;Set-Cfg $Config BackgroundColor '';return}}};'2'{Clear-Host;Write-Host '=== Solid Color ===';$keys=@($BackgroundColorPresets.Keys);for($i=0;$i-lt$keys.Count;$i++){Write-Host "$($i+1)) $($keys[$i]) [$($BackgroundColorPresets[$keys[$i]])]"};Write-Host "C) Custom hex`nB) Back";$x=Read-Host 'Choose';if($x-match'^[Bb]$'){continue};if($x-match'^[Cc]$'){$color=Normalize-HexColor (Read-Host 'Hex color')}else{$n=0;if(-not[int]::TryParse($x,[ref]$n)-or$n-lt1-or$n-gt$keys.Count){$color=$null}else{$color=$BackgroundColorPresets[$keys[$n-1]]}};if($color){Set-Cfg $Config BackgroundFileName '';Set-Cfg $Config BackgroundColor $color;return}else{Write-Warning 'Invalid color';Read-Host 'Press Enter'}};'3'{Set-Cfg $Config BackgroundFileName '';Set-Cfg $Config BackgroundColor '';return};{$_ -match '^[Bb]$'}{return};default{Write-Warning 'Invalid choice';Start-Sleep 1}}} }
function New-KioskHtml($Config){ $bg='background-color:#0b1220;'; if($Config.BackgroundFileName){$p=Join-Path $ScriptFolder $Config.BackgroundFileName;if(Test-Path -LiteralPath $p){$u=[Uri]::EscapeDataString([IO.Path]::GetFileName($Config.BackgroundFileName));$bg="background-color:#0b1220;background-image:url('$u');background-position:center;background-size:cover;background-repeat:no-repeat;"}} elseif($Config.BackgroundColor){$bg="background-color:$($Config.BackgroundColor);"}; $html=@"
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LobbyTime</title><style>html,body{height:100%;margin:0}body{display:flex;align-items:center;justify-content:center;color:$($Config.FontColor);font-family:$($Config.FontFamily);$bg}.overlay{position:fixed;inset:0;background:rgba(0,0,0,$($Config.OverlayOpacity));pointer-events:none}.container{position:relative;text-align:center;width:100%}.time{font-size:$($Config.TimeFontSize);font-weight:600;letter-spacing:2px;text-shadow:$($Config.TextShadow)}.date{font-size:$($Config.DateFontSize);margin-top:.5rem;opacity:.95;text-shadow:$($Config.TextShadow)}</style></head><body><div class="overlay"></div><div class="container"><div class="time" id="time">--:--</div><div class="date" id="date">Loading...</div></div><script>
function pad(n){return n.toString().padStart(2,'0')}function mn(){return ['January','February','March','April','May','June','July','August','September','October','November','December']}function ms(){return ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']}function wn(){return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']}function ws(){return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']}function fmt(d,f){return f.replace(/YYYY|YY|MMMM|MMM|MM|M|DD|D|dddd|ddd|HH|hh|mm|ss|A/g,function(t){switch(t){case'YYYY':return d.getFullYear();case'YY':return String(d.getFullYear()).slice(-2);case'MMMM':return mn()[d.getMonth()];case'MMM':return ms()[d.getMonth()];case'MM':return pad(d.getMonth()+1);case'M':return d.getMonth()+1;case'DD':return pad(d.getDate());case'D':return d.getDate();case'dddd':return wn()[d.getDay()];case'ddd':return ws()[d.getDay()];case'HH':return pad(d.getHours());case'hh':var h=d.getHours()%12;return pad(h===0?12:h);case'mm':return pad(d.getMinutes());case'ss':return pad(d.getSeconds());case'A':return d.getHours()>=12?'PM':'AM'}})}var tf='$($Config.TimeFormat)',df='$($Config.DateFormat)';function update(){var d=new Date();document.getElementById('time').textContent=fmt(d,tf);document.getElementById('date').textContent=fmt(d,df)}update();setInterval(update,1000);
</script></body></html>
"@; $html|Set-Content -LiteralPath $HtmlPath -Encoding UTF8; Write-Host "HTML written: $HtmlPath" }
function Find-Edge { foreach($p in @("${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe","$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe","$env:LOCALAPPDATA\Microsoft\Edge\Application\msedge.exe")){if($p-and(Test-Path -LiteralPath $p)){return $p}}; $c=Get-Command msedge.exe -ErrorAction SilentlyContinue;if($c){return $c.Source};return $null }
function Start-Edge([switch]$Kiosk){$e=Find-Edge;if(-not$e){Write-Warning 'Microsoft Edge not found.';return};$uri=([Uri]$HtmlPath).AbsoluteUri;if($Kiosk){Start-Process $e -ArgumentList @('--kiosk',$uri,'--edge-kiosk-type=fullscreen','--no-first-run')}else{Start-Process $e -ArgumentList @('--start-maximized','--no-first-run',$uri)}}
function Edit-Settings($Config){while($true){Clear-Host;Write-Host "=== Edit Settings ===`n1) Background`n2) Time Font Size [$($Config.TimeFontSize)]`n3) Date Font Size [$($Config.DateFontSize)]`n4) Font Family [$($Config.FontFamily)]`n5) Font Color [$($Config.FontColor)]`n6) Time Format [$($Config.TimeFormat)]`n7) Date Format [$($Config.DateFormat)]`nB) Back";$c=Read-Host 'Choose';switch($c){'1'{Edit-Background $Config};'2'{$v=Select-Map $FontSizePresets 'Time Font Size';if($v){Set-Cfg $Config TimeFontSize $v}};'3'{$v=Select-Map $FontSizePresets 'Date Font Size';if($v){Set-Cfg $Config DateFontSize $v}};'4'{$v=Select-Map $FontFamilyPresets 'Font Family';if($v){Set-Cfg $Config FontFamily $v}};'5'{$v=Select-Map $FontColorPresets 'Font Color';if($v){Set-Cfg $Config FontColor $v}};'6'{$v=Select-Map $TimeFormatPresets 'Time Format';if($v){Set-Cfg $Config TimeFormat $v}};'7'{$v=Select-Map $DateFormatPresets 'Date Format';if($v){Set-Cfg $Config DateFormat $v}};{$_-match'^[Bb]$'}{Save-Config $Config;return};default{Write-Warning 'Invalid choice';Start-Sleep 1}};Save-Config $Config}}

$config=Load-Config
if($BackgroundImage){$f=Copy-Background $BackgroundImage;if($f){Set-Cfg $config BackgroundFileName $f;Set-Cfg $config BackgroundColor ''}}
foreach($p in 'TimeFontSize','DateFontSize','FontFamily','TimeFormat','DateFormat'){if($PSBoundParameters.ContainsKey($p)){Set-Cfg $config $p (Get-Variable $p -ValueOnly)}}
if($FontColor){$fc=Normalize-HexColor $FontColor;if($fc){Set-Cfg $config FontColor $fc}}
Save-Config $config

if($Action -eq 'create'){New-KioskHtml $config;exit}
if($Action -eq 'kiosk'){New-KioskHtml $config;Start-Edge -Kiosk;exit}
if($Action -eq 'normal'){New-KioskHtml $config;Start-Edge;exit}
while($true){Clear-Host;Write-Host "=== LobbyTime v2.3 ===`n1) Create HTML only`n2) Create and launch Edge kiosk`n3) Create and launch Edge normal`n4) Edit settings`n5) Exit`n";$c=Read-Host 'Choose';switch($c){'1'{New-KioskHtml $config;Read-Host 'Press Enter'};'2'{New-KioskHtml $config;Start-Edge -Kiosk;Read-Host 'Press Enter'};'3'{New-KioskHtml $config;Start-Edge;Read-Host 'Press Enter'};'4'{Edit-Settings $config};'5'{Save-Config $config;return};default{Write-Warning 'Invalid choice';Start-Sleep 1}}}

